// Pseudo gateway budget check (high level)
async function handleEvent(event) {
  const budget = await redis.get(event.tenantId);
  if (budget <= 0) throw new Error('Budget exhausted');
  await redis.decr(event.tenantId, event.cost);
  forwardToTenantCompute(event);
}
```

